function renderMini(){const w=mini.width,h=mini.height,sx=w/WORLD.w,sy=h/WORLD.h;mc.fillStyle='#454c35';mc.fillRect(0,0,w,h);mc.globalAlpha=.27;mc.drawImage(terrain,0,0,w,h);mc.globalAlpha=1;mc.strokeStyle='#a6b97e14';for(let x=0;x<w;x+=w/8){mc.beginPath();mc.moveTo(x,0);mc.lineTo(x,h);mc.stroke();}for(const e of entities()){if(e.covered||e.type==='mineral'&&e.amount<=0)continue;const t=TYPES[e.type];mc.fillStyle=e.type==='mineral'?'#77bad1':e.type==='geyser'?'#94bb78':selected.includes(e.id)?'#f2edb6':'#b4d293';const ew=t.building?Math.max(4,t.w*sx):e.type==='mineral'?2:3,eh=t.building?Math.max(4,t.h*sy):3;mc.fillRect(e.x*sx-ew/2,e.y*sy-eh/2,ew,eh);}mc.strokeStyle='#e7e7c2';mc.lineWidth=1;mc.strokeRect((camera.x-view.w/2/camera.z)*sx,(camera.y-view.h/2/camera.z)*sy,view.w/camera.z*sx,view.h/camera.z*sy);}
